import React, { useEffect, useState, useRef } from 'react';
import Chart from 'chart.js/auto';
import api from '../utils/api';

const ChartComponent = () => {
    const [data, setData] = useState(null);
    const [error, setError] = useState(null);
    const [aircrafts, setAircrafts] = useState([]);
    const [selectedAircrafts, setSelectedAircrafts] = useState([]);
    const [years, setYears] = useState([]);
    const [selectedYears, setSelectedYears] = useState([]);
    const [months, setMonths] = useState(['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']);
    const [selectedMonths, setSelectedMonths] = useState([]);
    const chartRef = useRef(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                console.log('Fetched Data:', result.data);
                setData(result.data);

                // Extract unique aircrafts and years
                const invoicesTable = result.data.find(table => table.tableName === 'Invoices');
                const invoices = invoicesTable?.items || [];
                const uniqueAircrafts = Array.from(new Set(invoices.map(invoice => invoice.Aircraft)));
                setAircrafts(uniqueAircrafts);

                const uniqueYears = Array.from(new Set(invoices.map(invoice => {
                    const date = new Date(invoice['Trip start Z']);
                    return date.getFullYear();
                }))).filter(year => !isNaN(year));
                setYears(uniqueYears.sort((a, b) => a - b));

            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (!data) return;

        const invoicesTable = data.find(table => table.tableName === 'Invoices');
        const loggedFlightsTable = data.find(table => table.tableName === 'Logged-Flights');

        const invoices = invoicesTable?.items || [];
        const loggedFlights = loggedFlightsTable?.items || [];

        // Filter invoices with status "Invoiced"
        let filteredInvoices = invoices.filter(invoice => invoice.Status === 'Invoiced');

        if (selectedAircrafts.length > 0) {
            filteredInvoices = filteredInvoices.filter(invoice => selectedAircrafts.includes(invoice.Aircraft));
        }

        if (selectedYears.length > 0) {
            filteredInvoices = filteredInvoices.filter(invoice => selectedYears.includes(new Date(invoice['Trip start Z']).getFullYear()));
        }

        if (selectedMonths.length > 0) {
            const selectedMonthIndices = selectedMonths.map(month => months.indexOf(month));
            filteredInvoices = filteredInvoices.filter(invoice => selectedMonthIndices.includes(new Date(invoice['Trip start Z']).getMonth()));
        }

        const revenuePerHour = {};

        filteredInvoices.forEach(invoice => {
            const trip = invoice.Trip;
            const aircraft = invoice.Aircraft;
            const price = parseFloat(invoice.Price);

            // Get the flights matching the trip and aircraft
            const flights = loggedFlights.filter(flight => flight.Trip === trip && flight.Aircraft === aircraft);
            const totalFlightHours = flights.reduce((sum, flight) => sum + parseFloat(flight['Flight hrs']), 0);

            if (!revenuePerHour[aircraft]) {
                revenuePerHour[aircraft] = { totalPrice: 0, totalFlightHours: 0 };
            }

            revenuePerHour[aircraft].totalPrice += price;
            revenuePerHour[aircraft].totalFlightHours += totalFlightHours;
        });

        console.log('Revenue per Hour:', revenuePerHour);

        const labels = Object.keys(revenuePerHour);
        const dataPoints = labels.map(aircraft => {
            const { totalPrice, totalFlightHours } = revenuePerHour[aircraft];
            return (totalFlightHours > 0) ? (totalPrice / totalFlightHours).toFixed(2) : 0;
        });

        console.log('Chart Labels:', labels);
        console.log('Chart Data Points:', dataPoints);

        const ctx = document.getElementById('myChart').getContext('2d');

        // Destroy the previous chart instance if it exists
        if (chartRef.current) {
            chartRef.current.destroy();
        }

        // Create a new chart instance and save it to the ref
        chartRef.current = new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [{
                    label: 'Revenue per Hour',
                    data: dataPoints,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

    }, [data, selectedAircrafts, selectedYears, selectedMonths]);

    if (error) {
        return <div>{error}</div>;
    }

    const handleAircraftChange = (e) => {
        const value = e.target.value;
        setSelectedAircrafts(prev =>
            prev.includes(value) ? prev.filter(aircraft => aircraft !== value) : [...prev, value]
        );
    };

    const handleYearChange = (e) => {
        const value = parseInt(e.target.value);
        setSelectedYears(prev =>
            prev.includes(value) ? prev.filter(year => year !== value) : [...prev, value]
        );
    };

    const handleMonthChange = (e) => {
        const value = e.target.value;
        setSelectedMonths(prev =>
            prev.includes(value) ? prev.filter(month => month !== value) : [...prev, value]
        );
    };

    return (
        <div>
            <h1>Revenue per Hour of Aircrafts</h1>
            <div>
                <label>
                    Aircrafts:
                    {aircrafts.map(aircraft => (
                        <label key={aircraft}>
                            <input
                                type="checkbox"
                                value={aircraft}
                                checked={selectedAircrafts.includes(aircraft)}
                                onChange={handleAircraftChange}
                            />
                            {aircraft}
                        </label>
                    ))}
                </label>
                <label>
                    Years:
                    {years.map(year => (
                        <label key={year}>
                            <input
                                type="checkbox"
                                value={year}
                                checked={selectedYears.includes(year)}
                                onChange={handleYearChange}
                            />
                            {year}
                        </label>
                    ))}
                </label>
                <label>
                    Months:
                    {months.map((month, index) => (
                        <label key={index}>
                            <input
                                type="checkbox"
                                value={month}
                                checked={selectedMonths.includes(month)}
                                onChange={handleMonthChange}
                            />
                            {month}
                        </label>
                    ))}
                </label>
            </div>
            <canvas id="myChart" width="400" height="400"></canvas>
        </div>
    );
};

export default ChartComponent;
